import React, { useState, useEffect, useCallback, useRef } from 'react';
import { Flow } from 'flow-sdk';
import { useTimeline } from './hooks/useTimeline';
import { extractFrame } from './utils/video';
import { UploadedVideo } from './types';
import { suggestTransitionPrompt } from './services/geminiService';
import { 
  ERROR_AUTO_DISMISS_MS, 
  DEFAULT_VEO_MODEL, 
  VeoModelName, 
  DEFAULT_VEO_DURATION, 
  VeoDuration 
} from './constants';

import Timeline from './components/Timeline';
import ControlFooter from './components/ControlFooter';
import ProcessingOverlay from './components/ProcessingOverlay';

const App: React.FC = () => {
  const {
    timeline,
    isLoading,
    loadingMessage,
    isStitching,
    stitchingProgress,
    detectedResolution,
    addToTimeline,
    removeFromTimeline,
    reorderTimeline,
    generateTransitions,
    stitchAndSave,
  } = useTimeline();

  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [isProcessing, setIsProcessing] = useState(false);
  const [isSuggesting, setIsSuggesting] = useState(false);
  const [transitionHints, setTransitionHints] = useState<Record<string, string>>({});
  const [transitionRewriters, setTransitionRewriters] = useState<Record<string, boolean>>({});
  const [selectedModel, setSelectedModel] = useState<VeoModelName>(DEFAULT_VEO_MODEL);
  const [selectedDuration, setSelectedDuration] = useState<VeoDuration>(DEFAULT_VEO_DURATION);

  const suggestionRef = useRef<string | null>(null);

  const handleHintChange = useCallback((slotKey: string, hint: string) => {
    setTransitionHints(prev => ({ ...prev, [slotKey]: hint }));
    setTransitionRewriters(prev => prev[slotKey] === undefined ? { ...prev, [slotKey]: true } : prev);
  }, []);

  const handleRewriterChange = useCallback((slotKey: string, enabled: boolean) => {
    setTransitionRewriters(prev => ({ ...prev, [slotKey]: enabled }));
  }, []);

  useEffect(() => {
    if (!error && !success) return;
    const timer = setTimeout(() => { setError(null); setSuccess(null); }, ERROR_AUTO_DISMISS_MS);
    return () => clearTimeout(timer);
  }, [error, success]);

  // Effect: Auto-suggest prompt when 2 clips are present
  useEffect(() => {
    const videos = timeline.filter((t): t is { type: 'video'; data: UploadedVideo } => t.type === 'video');
    if (videos.length === 2) {
      const vA = videos[0].data;
      const vB = videos[1].data;
      const key = `${vA.id}→${vB.id}`;

      // Only suggest if we haven't already and the field is empty
      if (!transitionHints[key] && !isSuggesting && suggestionRef.current !== key) {
        suggestionRef.current = key;
        setIsSuggesting(true);
        suggestTransitionPrompt(vA.endThumbnail, vB.startThumbnail)
          .then(suggestion => {
            setTransitionHints(prev => ({ ...prev, [key]: suggestion }));
          })
          .catch(err => {
            console.error('Failed to auto-suggest prompt:', err);
          })
          .finally(() => {
            setIsSuggesting(false);
          });
      }
    } else {
      suggestionRef.current = null;
    }
  }, [timeline, transitionHints, isSuggesting]);

  // Handle direct gallery import and frame extraction
  const handleGalleryImport = useCallback(async () => {
    try {
      const item = await Flow.media.select({ filter: 'video' });
      if (!item) return;

      setIsProcessing(true);

      const bytes = Uint8Array.from(atob(item.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: item.mimeType || 'video/mp4' });
      const file = new File([blob], item.name || `clip-${item.mediaId}.mp4`, { type: item.mimeType || 'video/mp4' });

      // Extract both the true start and true end frames for the preview split
      const [startThumbnail, endThumbnail] = await Promise.all([
        extractFrame(file, 'start'),
        extractFrame(file, 'end')
      ]);

      const newVideo: UploadedVideo = {
        id: `${file.name}-${Date.now()}-${Math.random()}`,
        file,
        startThumbnail,
        endThumbnail,
        url: URL.createObjectURL(file),
      };

      addToTimeline(newVideo);
      setIsProcessing(false);
    } catch (err: any) {
      setIsProcessing(false);
      if (err?.message && !/cancel/i.test(err.message)) {
        setError(err.message);
      }
    }
  }, [addToTimeline]);

  const handleGenerate = useCallback(async () => {
    const res = await generateTransitions(selectedModel, selectedDuration, transitionHints, transitionRewriters);
    if (res.error) setError(res.error);
  }, [generateTransitions, selectedModel, selectedDuration, transitionHints, transitionRewriters]);

  const handleSaveToGrid = useCallback(async () => {
    const err = await stitchAndSave();
    if (err) {
      setError(err);
    } else {
      setSuccess("✓ Composition saved to your Media Gallery");
    }
  }, [stitchAndSave]);

  const videoCount = timeline.filter(t => t.type === 'video').length;
  const hasTransitions = timeline.some(t => t.type === 'transition');
  const allDone = hasTransitions && timeline.every(t => t.type !== 'transition' || t.data.status === 'done');

  return (
    <div className="min-h-screen bg-[#0e0e0e] text-white flex flex-col relative overflow-hidden">
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute rounded-full blur-[120px] opacity-[0.07]" style={{ width: '600px', height: '600px', background: 'radial-gradient(circle, #1e3a8a 0%, transparent 70%)', animation: 'halation-drift-1 25s ease-in-out infinite', bottom: '-10%', left: '-5%' }} />
        <div className="absolute rounded-full blur-[100px] opacity-[0.05]" style={{ width: '500px', height: '500px', background: 'radial-gradient(circle, #c2410c 0%, transparent 70%)', animation: 'halation-drift-2 30s ease-in-out infinite', top: '-8%', right: '-3%' }} />
      </div>

      <nav className="h-20 flex items-center px-10 border-b border-white/15 bg-black/50 backdrop-blur-xl shrink-0">
        {/* Navigation placeholder */}
      </nav>

      <main className="flex-1 flex flex-col items-center justify-center">
        <Timeline 
          timeline={timeline} 
          transitionHints={transitionHints} 
          transitionRewriters={transitionRewriters} 
          onHintChange={handleHintChange} 
          onRewriterChange={handleRewriterChange} 
          onRemove={removeFromTimeline} 
          onReorder={reorderTimeline} 
          onImport={handleGalleryImport}
          onRetry={handleGenerate}
          isSuggesting={isSuggesting}
        />
      </main>

      {/* Enhanced Global Notification */}
      {(error || success) && (
        <div className="fixed top-24 left-1/2 -translate-x-1/2 z-[200] w-full max-w-md px-6 animate-fade-in">
          <div className={`flex items-center gap-4 p-4 rounded-2xl shadow-2xl backdrop-blur-xl border ${
            error ? 'bg-red-900/20 border-red-500/50 text-white' : 'bg-emerald-900/20 border-emerald-500/50 text-white'
          }`}>
            <span className={`material-symbols-outlined text-[20px] ${error ? 'text-red-400' : 'text-emerald-400'}`}>
              {error ? 'warning' : 'check_circle'}
            </span>
            <div className="flex-1 flex flex-col gap-0.5">
              <span className="text-[10px] font-black uppercase tracking-wider">
                {error ? 'Operational Error' : 'Success'}
              </span>
              <p className="text-[11px] font-medium leading-tight opacity-90">
                {error || success}
              </p>
            </div>
            <button onClick={() => { setError(null); setSuccess(null); }} className="p-1 hover:bg-white/10 rounded-full transition-colors">
              <span className="material-symbols-outlined text-[18px] opacity-50">close</span>
            </button>
          </div>
        </div>
      )}

      <ControlFooter 
        loadingMessage={isProcessing ? 'Analyzing Clip...' : loadingMessage} 
        canGenerate={videoCount >= 2 && !hasTransitions} 
        canExport={allDone} 
        isLoading={isLoading || isProcessing} 
        detectedResolution={detectedResolution} 
        selectedModel={selectedModel}
        onModelChange={setSelectedModel}
        selectedDuration={selectedDuration}
        onDurationChange={setSelectedDuration}
        onGenerate={handleGenerate} 
        onExport={handleSaveToGrid} 
      />

      {(isLoading || isStitching || isProcessing) && (
        <ProcessingOverlay 
          isStitching={isStitching} 
          loadingMessage={isProcessing ? 'Extracting high-fidelity frame references for AI analysis...' : loadingMessage} 
          stitchingProgress={stitchingProgress} 
        />
      )}

      <style>{`
        html, body, #root { 
          font-family: 'Google Sans Text', 'Google Sans', -apple-system, BlinkMacSystemFont, sans-serif; 
          background-color: #0e0e0e; 
          color: #ffffff; 
          margin: 0; 
          padding: 0;
          height: 100%;
          width: 100%;
          -webkit-font-smoothing: antialiased; 
          -moz-osx-font-smoothing: grayscale;
          letter-spacing: -0.01em;
        }
        * { font-family: inherit; box-sizing: border-box; }
        ::-webkit-scrollbar { width: 4px; height: 4px; }
        ::-webkit-scrollbar-thumb { background: rgba(255, 255, 255, 0.2); border-radius: 10px; }
        @keyframes halation-drift-1 { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(15vw, -10vh); } }
        @keyframes halation-drift-2 { 0%, 100% { transform: translate(0, 0); } 50% { transform: translate(-20vw, 15vh); } }
        .animate-fade-in { animation: fadeIn 0.3s ease-out forwards; }
        @keyframes fadeIn { from { opacity: 0; transform: translate(-50%, 10px); } to { opacity: 1; transform: translate(-50%, 0); } }
      `}</style>
    </div>
  );
};

export default App;

export interface UploadedVideo {
  id: string;
  file: File;
  startThumbnail: string; // Base64 PNG of the first frame
  endThumbnail: string;   // Base64 PNG of the last frame
  url: string;            // Blob URL for previewing
}

export interface GeneratedTransition {
  id: string;
  url: string;
  status: 'generating' | 'done' | 'failed';
  prompt?: string;
  error?: string; // Descriptive error message for failed attempts
}

export type TimelineItem = 
  | { type: 'video'; data: UploadedVideo }
  | { type: 'transition'; data: GeneratedTransition };

export interface AppState {
  timeline: TimelineItem[];
}

// ── Model Configuration ──────────────────────────────────────────────
/**
 * Available video models in the Flow SDK.
 */
export const VEO_MODELS = [
  'Veo 3.1 - Lite',
] as const;

export type VeoModelName = typeof VEO_MODELS[number];

export const DEFAULT_VEO_MODEL: VeoModelName = 'Veo 3.1 - Lite';

/**
 * Supported durations for Veo 3.1 models.
 */
export const VEO_DURATIONS = [4, 6, 8] as const;
export type VeoDuration = typeof VEO_DURATIONS[number];
export const DEFAULT_VEO_DURATION: VeoDuration = 8;

// ── Polling & Timing ─────────────────────────────────────────────────
export const POLLING_INTERVAL_MS = 10_000;
export const FRAME_EXTRACT_DELAY_MS = 150;
export const STITCH_INTER_CLIP_DELAY_MS = 100;

// ── Video Encoding ───────────────────────────────────────────────────
export const STITCH_FPS = 30;
export const STITCH_BITRATE = 20_000_000; // 20 Mbps for Premiere-quality output

/**
 * Preferred MP4/H.264 for Premiere Pro compatibility.
 * Falls back to VP9 WebM if the browser doesn't support MP4 recording.
 */
export const STITCH_MIME_PREFERENCES = [
  'video/mp4; codecs=avc1.640028',   // H.264 High Profile — Premiere native
  'video/mp4; codecs=avc1.42E01E',   // H.264 Baseline — broad compat
  'video/mp4',                        // Generic MP4
  'video/webm; codecs=vp9',           // VP9 fallback
  'video/webm; codecs=vp8',           // VP8 last resort
] as const;

// ── Video Generation Defaults ────────────────────────────────────────
export const VIDEO_ASPECT_RATIO = '16:9' as const;

// ── UX Timings ───────────────────────────────────────────────────────
export const ERROR_AUTO_DISMISS_MS = 6_000;

// ── Frame Extraction ─────────────────────────────────────────────────
/**
 * For transition frames ('start' / 'end'), we extract at the TRUE first/last frame
 * so the Veo model receives pixel-accurate reference images.
 */
export const FRAME_IMAGE_FORMAT = 'image/png' as const;
/** How far into the video to seek for thumbnail extraction (avoids black leader) */
export const THUMBNAIL_SEEK_SECONDS = 1.0;
export const THUMBNAIL_SEEK_RATIO = 0.25;

import { useState, useCallback, useEffect, useMemo } from 'react';
import { Flow } from 'flow-sdk';
import { TimelineItem, UploadedVideo } from '../types';
import { extractFrame, getVideoResolution, VeoResolution } from '../utils/video';
import { generateTransitionVideo } from '../services/geminiService';
import { stitchTimeline } from '../utils/stitcher';
import { VeoModelName, VeoDuration } from '../constants';

const blobToBase64 = (blob: Blob): Promise<string> =>
  new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onloadend = () => {
      const result = reader.result as string;
      const commaIdx = result.indexOf(',');
      resolve(commaIdx !== -1 ? result.substring(commaIdx + 1) : result);
    };
    reader.onerror = () => reject(new Error('Failed to read blob'));
    reader.readAsDataURL(blob);
  });

interface VideoResolutionInfo {
  width: number;
  height: number;
  veoTier: VeoResolution;
}

interface UseTimelineReturn {
  timeline: TimelineItem[];
  isLoading: boolean;
  loadingMessage: string;
  isStitching: boolean;
  stitchingProgress: number;
  detectedResolution: { width: number; height: number; tier: VeoResolution } | null;
  addToTimeline: (video: UploadedVideo) => void;
  removeFromTimeline: (index: number) => void;
  reorderTimeline: (fromIndex: number, toIndex: number) => void;
  clearTimeline: () => void;
  generateTransitions: (model: VeoModelName, duration: VeoDuration, hints?: Record<string, string>, rewriters?: Record<string, boolean>) => Promise<{ error?: string }>;
  stitchAndSave: () => Promise<string | null>;
}

export const useTimeline = (): UseTimelineReturn => {
  const [timeline, setTimeline] = useState<TimelineItem[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [loadingMessage, setLoadingMessage] = useState<string>('');
  const [isStitching, setIsStitching] = useState<boolean>(false);
  const [stitchingProgress, setStitchingProgress] = useState<number>(0);
  const [resolutions, setResolutions] = useState<Record<string, VideoResolutionInfo>>({});

  const videoIds = useMemo(
    () => timeline.filter(t => t.type === 'video').map(t => (t.data as UploadedVideo).id),
    [timeline]
  );

  useEffect(() => {
    for (const item of timeline) {
      if (item.type !== 'video') continue;
      const video = item.data as UploadedVideo;
      if (resolutions[video.id]) continue;
      getVideoResolution(video.file).then(res => {
        setResolutions(prev => ({ ...prev, [video.id]: res }));
      }).catch(() => {});
    }
  }, [videoIds]);

  const detectedResolution = useMemo(() => {
    const activeResolutions = videoIds.map(id => resolutions[id]).filter(Boolean);
    if (activeResolutions.length === 0) return null;
    let lowest = activeResolutions[0];
    for (const res of activeResolutions) {
      if (res.height < lowest.height) lowest = res;
    }
    return { width: lowest.width, height: lowest.height, tier: '720p' as VeoResolution };
  }, [videoIds, resolutions]);

  const addToTimeline = useCallback((video: UploadedVideo) => {
    setTimeline(prev => {
      const vids = prev.filter(t => t.type === 'video');
      if (vids.length >= 2) return prev; // Limit to 2
      return [...prev, { type: 'video', data: video }];
    });
  }, []);

  const removeFromTimeline = useCallback((index: number) => {
    setTimeline(prev => {
      const next = [...prev];
      next.splice(index, 1);
      // Clean up transitions if they no longer have neighbors
      const cleaned = next.filter((item, i) => {
        if (item.type !== 'transition') return true;
        const hasBefore = i > 0 && next[i - 1]?.type === 'video';
        const hasAfter = i < next.length - 1 && next[i + 1]?.type === 'video';
        return hasBefore && hasAfter;
      });
      return cleaned;
    });
  }, []);

  const reorderTimeline = useCallback((fromIndex: number, toIndex: number) => {
    setTimeline(prev => {
      const videosOnly = prev.filter(item => item.type === 'video');
      const [moved] = videosOnly.splice(fromIndex, 1);
      if (!moved) return prev;
      const videoIndices = prev.map((item, i) => (item.type === 'video' ? i : -1)).filter(i => i !== -1);
      const next = [...prev];
      const [dragged] = next.splice(videoIndices[fromIndex], 1);
      const updatedIndices = next.map((item, i) => (item.type === 'video' ? i : -1)).filter(i => i !== -1);
      const insertAt = toIndex >= updatedIndices.length ? next.length : updatedIndices[toIndex];
      next.splice(insertAt, 0, dragged);
      return next;
    });
  }, []);

  const generateTransitions = useCallback(async (model: VeoModelName, duration: VeoDuration, hints?: Record<string, string>, rewriters?: Record<string, boolean>) => {
    const videos = timeline.filter((i): i is { type: 'video'; data: UploadedVideo } => i.type === 'video');
    if (videos.length < 2) return { error: 'Need exactly two clips.' };
    setIsLoading(true);

    // Standardize timeline to [V1, T, V2]
    const nextTimeline: TimelineItem[] = [
      videos[0],
      { type: 'transition', data: { id: `trans-${Date.now()}-0`, url: '', status: 'generating' } },
      videos[1]
    ];
    setTimeline(nextTimeline);

    let errorMsg: string | undefined;
    const vA = videos[0].data;
    const vB = videos[1].data;
    const key = `${vA.id}→${vB.id}`;

    try {
      const url = await generateTransitionVideo(
        await extractFrame(vA.file, 'end'), 
        await extractFrame(vB.file, 'start'), 
        setLoadingMessage, 
        model,
        duration,
        '720p', 
        hints?.[key], 
        rewriters?.[key]
      );
      setTimeline(prev => prev.map(t => t.type === 'transition' ? { ...t, data: { ...t.data, url, status: 'done', error: undefined } } : t));
    } catch (err: any) {
      errorMsg = err?.message || 'Transition failed.';
      setTimeline(prev => prev.map(t => t.type === 'transition' ? { ...t, data: { ...t.data, status: 'failed', error: errorMsg } } : t));
    }

    setIsLoading(false);
    setLoadingMessage('');
    return { error: errorMsg };
  }, [timeline]);

  const stitchAndSave = useCallback(async (): Promise<string | null> => {
    setIsStitching(true);
    setStitchingProgress(0);
    try {
      const { blob, sdkMime } = await stitchTimeline(timeline, setStitchingProgress);
      const base64 = await blobToBase64(blob);
      await Flow.save({ base64, mimeType: sdkMime, name: `Transition-Machine-${Date.now()}` });
      return null;
    } catch (err: any) {
      return `Failed to save: ${err?.message || 'Unknown error'}`;
    } finally {
      setIsStitching(false);
    }
  }, [timeline]);

  return { timeline, isLoading, loadingMessage, isStitching, stitchingProgress, detectedResolution, addToTimeline, removeFromTimeline, reorderTimeline, clearTimeline: () => setTimeline([]), generateTransitions, stitchAndSave };
};

import { Flow } from 'flow-sdk';
import { VIDEO_ASPECT_RATIO, VeoModelName, VeoDuration } from '../constants';
import type { VeoResolution } from '../utils/video';

// ── System Prompt ────────────────────────────────────────────────────

const TRANSITION_SYSTEM_INSTRUCTION = `You are a visionary Cinematographer specializing in "Match-Cut" and "Continuous Take" transitions. You will receive two images: the LAST FRAME of Scene A and the FIRST FRAME of Scene B. Your goal is to script a seamless camera movement that physically and dynamically bridges these two moments without a single edit.

**--- THE CORE MECHANISM: DYNAMIC CAMERA MOTION ---**
Do NOT rely on environmental changes alone. The camera itself MUST MOVE to discover the new scene. 
- **Vector Matching:** If Image 1 suggests a slight pan right, the transition MUST accelerate that pan or continue it smoothly into Image 2.
- **The Physical Push:** Use a dolly-in or push-through. The camera travels *through* a gap, a window, or a foreground object in Scene A and emerges in Scene B.
- **The Tracking Handoff:** Follow a moving subject in Scene A (a person, a car, a ball) as it crosses the frame, and use its motion as a "wiper" that pulls the environment of Scene B into view behind it.

**--- SCRIPTING THE CONTINUITY ---**
1. **Match Motion Vectors:** Analyze the visual flow of Image 1 and 2. If Scene B starts with a fast movement, the transition must build that momentum.
2. **The Kinetic Bridge:** Describe how the camera travels. E.g., "The camera dollys forward rapidly, passing through the open window of the cabin; as it exits the window frame, the environment has instantly transitioned to the open mountain range of the next clip."
3. **Subject-Led Discovery:** "A character walks past the lens from left to right. The camera tracks with them, and as they step out of frame, the background has shifted from the office to the beach."

**--- ABSOLUTE PROHIBITIONS (STRICT ENFORCEMENT) ---**
- **NO FADES / CROSS-DISSOLVES:** Do not mention fading, dissolving, or "merging." The transition must be a sharp, physical movement.
- **NO STATIC TRANSITIONS:** Do not just "look" at a doorway and have it change. The camera MUST travel through the doorway.
- **NO WIPES / SLIDES:** No post-production "push" or "slide" effects.
- **NO BLURS / WHIPS:** No "whip pan to black" or "motion blur masking."
- **NO GHOSTING:** No translucent overlays or double exposures.

**--- OUTPUT FORMAT ---**
Output ONLY the video generation prompt. One paragraph, 2-4 sentences. Focus on the kinetic energy and camera path. No meta-commentary.`;

// ── Helpers ──────────────────────────────────────────────────────────

const stripBase64Prefix = (dataUrl: string): string => {
  const commaIdx = dataUrl.indexOf(',');
  return commaIdx !== -1 ? dataUrl.substring(commaIdx + 1) : dataUrl;
};

const toCompressedJpeg = (pngDataUrl: string, quality = 0.7): Promise<string> => {
  return new Promise((resolve, reject) => {
    const img = new Image();
    img.onload = () => {
      const canvas = document.createElement('canvas');
      canvas.width = img.width;
      canvas.height = img.height;
      const ctx = canvas.getContext('2d');
      if (!ctx) return reject(new Error('Canvas context unavailable'));
      ctx.drawImage(img, 0, 0);
      resolve(canvas.toDataURL('image/jpeg', quality));
    };
    img.onerror = () => reject(new Error('Failed to load image for compression'));
    img.src = pngDataUrl;
  });
};

const buildUserInstruction = (userHint?: string): string => {
  const base = `Study these two frames. 
IMAGE 1: Last frame of the outgoing clip.
IMAGE 2: First frame of the incoming clip.

Describe a KINETIC CAMERA MOVEMENT (push, pan, or track) that bridges these two moments. The camera must never stop rolling and there must be NO FADES.`;

  if (userHint) {
    return `${base}\n\n**USER HINT:** Incorporate this event: "${userHint}"\nEnsure the camera motion is the primary driver of the transition.`;
  }
  return base;
};

// ── Service Methods ──────────────────────────────────────────────────

/**
 * Generates a creative prompt suggestion based on the visual flow between two frames.
 */
export const suggestTransitionPrompt = async (
  startFrameBase64: string,
  endFrameBase64: string,
  userHint?: string
): Promise<string> => {
  const startJpeg = await toCompressedJpeg(startFrameBase64);
  const endJpeg = await toCompressedJpeg(endFrameBase64);

  const { text } = await Flow.generate.text(buildUserInstruction(userHint), {
    systemInstruction: TRANSITION_SYSTEM_INSTRUCTION,
    thinkingLevel: 'low',
    images: [
      { base64: stripBase64Prefix(startJpeg), mimeType: 'image/jpeg' },
      { base64: stripBase64Prefix(endJpeg), mimeType: 'image/jpeg' },
    ],
  });

  if (!text) throw new Error('Prompt model returned an empty response.');
  return text.trim();
};

/**
 * Renders the final transition video.
 */
export const generateTransitionVideo = async (
  startFrameBase64: string,
  endFrameBase64: string,
  onStatusUpdate: (message: string) => void,
  modelDisplayName: VeoModelName,
  durationSeconds: VeoDuration,
  _resolution: VeoResolution = '1080p',
  userHint?: string,
  enableRewriter: boolean = true
): Promise<string> => {
  onStatusUpdate('Orchestrating camera move…');
  let creativePrompt: string;

  if (enableRewriter || !userHint) {
    creativePrompt = await suggestTransitionPrompt(startFrameBase64, endFrameBase64, userHint);
  } else {
    creativePrompt = userHint.trim();
  }

  onStatusUpdate(`Generating: "${creativePrompt}". Rendering continuous take.`);

  const finalPrompt = `${creativePrompt}

MANDATORY TECHNICAL SPECS: 
1. ONE CONTINUOUS TAKE. The camera never cuts and the screen never goes dark.
2. NO CROSSFADES OR DISSOLVES. The transition must be 100% physical and driven by camera motion.
3. VECTOR MATCHING. Match the velocity and direction of Image 1 and Image 2 perfectly.
4. ABSOLUTELY NO FADING. Do not use opacity changes to bridge the gap. Use a physical camera push or subject-led reveal.`;

  const uploadToGallery = async (b64: string, name: string) => {
    const payload = { base64: stripBase64Prefix(b64), mimeType: 'image/png' as const, name };
    if (typeof (Flow.media as any).upload === 'function') {
      return await (Flow.media as any).upload(payload);
    }
    return await Flow.save(payload);
  };

  const { mediaId: startMediaId } = await uploadToGallery(startFrameBase64, 'Transition Start Frame');
  const { mediaId: endMediaId } = await uploadToGallery(endFrameBase64, 'Transition End Frame');

  const video = await Flow.generate.video({
    prompt: finalPrompt,
    firstFrameImageMediaId: startMediaId,
    lastFrameImageMediaId: endMediaId,
    aspectRatio: '16:9',
    modelDisplayName: modelDisplayName,
    durationSeconds: durationSeconds, 
  });

  if (!video?.base64) throw new Error('Video generation failed to return data.');
  return `data:${video.mimeType};base64,${video.base64}`;
};

import {
  FRAME_EXTRACT_DELAY_MS,
  FRAME_IMAGE_FORMAT,
  THUMBNAIL_SEEK_SECONDS,
  THUMBNAIL_SEEK_RATIO,
} from '../constants';

/**
 * Extracts a frame from a video file at a specific time.
 *
 * For 'start' and 'end', seeks to the TRUE first/last frame of the video
 * so that Veo receives pixel-accurate reference images for transitions.
 *
 * For 'thumbnail', seeks slightly into the video to avoid black leader frames.
 *
 * @param videoFile The video file to process.
 * @param time      'start' for the actual first frame, 'end' for the actual last frame,
 *                  'thumbnail' for a representative frame near the beginning.
 * @returns A promise that resolves with the base64-encoded PNG data-URL of the frame.
 */
export const extractFrame = (
  videoFile: File,
  time: 'start' | 'end' | 'thumbnail'
): Promise<string> => {
  return new Promise((resolve, reject) => {
    const video = document.createElement('video');
    video.preload = 'auto'; // 'auto' ensures full buffering for accurate seeking
    video.muted = true;
    video.playsInline = true;

    // Append to DOM off-screen to ensure reliable rendering in all browsers
    video.style.position = 'fixed';
    video.style.top = '-9999px';
    video.style.left = '-9999px';
    video.style.opacity = '0';
    video.style.pointerEvents = 'none';
    document.body.appendChild(video);

    const url = URL.createObjectURL(videoFile);
    video.src = url;

    const canvas = document.createElement('canvas');
    const ctx = canvas.getContext('2d');

    /** Centralized cleanup for all exit paths */
    const cleanup = () => {
      URL.revokeObjectURL(url);
      if (document.body.contains(video)) {
        document.body.removeChild(video);
      }
      canvas.remove();
    };

    if (!ctx) {
      cleanup();
      return reject(new Error('Could not get canvas context.'));
    }

    const captureFrame = () => {
      // Small delay to ensure the frame buffer is fully populated
      setTimeout(() => {
        try {
          canvas.width = video.videoWidth;
          canvas.height = video.videoHeight;
          ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
          // Use lossless PNG for maximum fidelity in reference frames
          const frameDataUrl = canvas.toDataURL(FRAME_IMAGE_FORMAT);
          cleanup();
          resolve(frameDataUrl);
        } catch (error) {
          cleanup();
          reject(error);
        }
      }, FRAME_EXTRACT_DELAY_MS);
    };

    const onLoadedMetadata = () => {
      const duration = video.duration || 0;

      if (time === 'start') {
        // TRUE first frame — seek to time 0
        video.currentTime = 0;
      } else if (time === 'end') {
        // TRUE last frame — seek as close to the end as the browser allows.
        // Most browsers can't seek to exactly `duration`, so we use a tiny epsilon.
        if (isFinite(duration) && duration > 0) {
          video.currentTime = Math.max(0, duration - 0.05);
        } else {
          video.currentTime = 0;
        }
      } else {
        // 'thumbnail' — skip into the video to find a non-black representative frame
        let targetTime = Math.min(THUMBNAIL_SEEK_SECONDS, duration * THUMBNAIL_SEEK_RATIO);
        if (targetTime === 0 && duration > 0.1) targetTime = 0.1;
        video.currentTime = targetTime;
      }
    };

    video.addEventListener('seeked', captureFrame, { once: true });
    video.addEventListener('loadedmetadata', onLoadedMetadata, { once: true });

    video.addEventListener(
      'error',
      () => {
        let errorMessage = video.error ? video.error.message : 'Unknown error';
        if (video.error) {
          if (video.error.code === 4) {
            errorMessage = "Unsupported video codec (e.g., ProRes or HEVC). Your browser cannot natively decode this file. Please convert it to a standard H.264 MP4 before importing.";
          } else if (video.error.code === 3 || errorMessage.includes('PIPELINE_ERROR_DECODE')) {
            errorMessage = "Hardware decoding failed. This is a common issue with certain WebM or complex MP4 files on Chromium/Mac. Please convert the file to a standard H.264 MP4 before importing.";
          } else {
            errorMessage = `${errorMessage} (code: ${video.error.code})`;
          }
        }
        cleanup();
        reject(new Error(errorMessage));
      },
      { once: true }
    );

    video.load();
  });
};

// ── Veo-supported resolution tiers ──────────────────────────────────

/** Resolution tiers that Veo 3.1 natively supports */
export type VeoResolution = '720p' | '1080p';

/**
 * Detects the native resolution of a video file and maps it to the
 * nearest Veo-supported tier.
 *
 * Updated: Defaulting to 720p as the baseline tier.
 */
export const getVideoResolution = (videoFile: File): Promise<{ width: number; height: number; veoTier: VeoResolution }> => {
  return new Promise((resolve, reject) => {
    const video = document.createElement('video');
    video.preload = 'metadata';
    video.muted = true;

    video.style.position = 'fixed';
    video.style.top = '-9999px';
    video.style.left = '-9999px';
    video.style.opacity = '0';
    document.body.appendChild(video);

    const url = URL.createObjectURL(videoFile);
    video.src = url;

    const cleanup = () => {
      URL.revokeObjectURL(url);
      if (document.body.contains(video)) document.body.removeChild(video);
    };

    video.addEventListener('loadedmetadata', () => {
      const w = video.videoWidth;
      const h = video.videoHeight;
      cleanup();
      // Map to Veo tier: Defaulting to 720p as requested.
      const veoTier: VeoResolution = '720p';
      resolve({ width: w, height: h, veoTier });
    }, { once: true });

    video.addEventListener('error', () => {
      let errorMessage = video.error ? video.error.message : 'Unknown error';
      if (video.error) {
        if (video.error.code === 4) {
          errorMessage = "Unsupported video codec. Your browser cannot natively decode this file. Please convert it to a standard H.264 MP4 before importing.";
        } else if (video.error.code === 3 || errorMessage.includes('PIPELINE_ERROR_DECODE')) {
          errorMessage = "Hardware decoding failed. This is a common issue with certain WebM or complex MP4 files on Chromium/Mac. Please convert the file to a standard H.264 MP4 before importing.";
        } else {
          errorMessage = `${errorMessage} (code: ${video.error.code})`;
        }
      }
      cleanup();
      reject(new Error(errorMessage));
    }, { once: true });

    video.load();
  });
};

import { 
  Input, Output, Conversion, 
  Mp4OutputFormat, BufferTarget, BlobSource, ALL_FORMATS,
  canEncodeAudio
} from 'mediabunny';
import { registerAc3Decoder, registerAc3Encoder } from '@mediabunny/ac3';
import { registerMp3Encoder } from '@mediabunny/mp3-encoder';
import { TimelineItem } from '../types';
import {
  STITCH_FPS,
  STITCH_BITRATE,
  STITCH_MIME_PREFERENCES,
} from '../constants';

// ── Audio Encoder Initialization ─────────────────────────────────────

let encodersInitialized = false;

async function initEncoders() {
  if (encodersInitialized) return;
  try {
    registerAc3Decoder();
    registerAc3Encoder();
    if (!(await canEncodeAudio('mp3'))) {
      registerMp3Encoder();
    }
  } catch (e) {
    console.warn('Audio encoder registration skipped or failed:', e);
  }
  encodersInitialized = true;
}

// ── Helpers ──────────────────────────────────────────────────────────

const selectBestMime = (): { mimeType: string; sdkMime: 'video/mp4' } => {
  for (const mime of STITCH_MIME_PREFERENCES) {
    if (MediaRecorder.isTypeSupported(mime)) {
      return { mimeType: mime, sdkMime: 'video/mp4' };
    }
  }
  throw new Error('No supported video codec found for recording.');
};

const getVideoDimensions = (url: string): Promise<{ width: number; height: number }> => {
  return new Promise((resolve, reject) => {
    const video = document.createElement('video');
    video.preload = 'metadata';
    video.src = url;
    video.onloadedmetadata = () => {
      resolve({ width: video.videoWidth, height: video.videoHeight });
      video.remove();
    };
    video.onerror = () => {
      video.remove();
      reject(new Error(`Could not load metadata for video: ${url}`));
    };
  });
};

const processVideoClip = async (
  videoUrl: string,
  canvas: HTMLCanvasElement,
  ctx: CanvasRenderingContext2D,
  onProgress: (p: number) => void
): Promise<void> => {
  return new Promise((resolve, reject) => {
    const video = document.createElement('video');
    video.muted = true;
    video.playsInline = true;
    video.src = videoUrl;
    video.crossOrigin = 'anonymous';

    const cleanup = () => {
      if (document.body.contains(video)) document.body.removeChild(video);
    };

    video.onloadedmetadata = async () => {
      const duration = video.duration;
      const frameDuration = 1 / STITCH_FPS;
      let currentTime = 0;

      try {
        while (currentTime < duration) {
          video.currentTime = currentTime;
          await new Promise((r) => {
            const onSeeked = () => {
              video.removeEventListener('seeked', onSeeked);
              r(null);
            };
            video.addEventListener('seeked', onSeeked);
          });

          const scale = Math.max(canvas.width / video.videoWidth, canvas.height / video.videoHeight);
          const x = (canvas.width / 2) - (video.videoWidth / 2) * scale;
          const y = (canvas.height / 2) - (video.videoHeight / 2) * scale;

          ctx.fillStyle = 'black';
          ctx.fillRect(0, 0, canvas.width, canvas.height);
          ctx.drawImage(video, x, y, video.videoWidth * scale, video.videoHeight * scale);

          currentTime += frameDuration;
          onProgress(currentTime / duration);
        }
        cleanup();
        resolve();
      } catch (err) {
        cleanup();
        reject(err);
      }
    };

    video.onerror = () => {
      cleanup();
      reject(new Error('Failed to load video for stitching.'));
    };

    document.body.appendChild(video);
    video.load();
  });
};

// ── Main Stitching Engine ───────────────────────────────────────────

/**
 * Stitches the timeline into a single, high-compatibility MP4 file.
 * 
 * Workflow:
 * 1. Record deterministic canvas frames into a temporary Blob using MediaRecorder.
 * 2. Pass the Blob through MediaBunny to "Sanitize" the file.
 * 3. MediaBunny applies `fastStart: 'in-memory'`, which moves the moov atom to the front.
 * 4. This resolves the 500 errors on the server side and ensures instant playback.
 */
export const stitchTimeline = async (
  timeline: TimelineItem[],
  onProgress: (progress: number) => void
): Promise<{ blob: Blob; sdkMime: 'video/mp4' }> => {
  const playableItems = timeline.filter(
    item =>
      item.type === 'video' ||
      (item.type === 'transition' && item.data.status === 'done')
  );

  if (playableItems.length === 0) throw new Error('Timeline is empty.');

  // Step 1: Initialize Deterministic Capture
  const videoUrls = playableItems.map(item => item.data.url);
  const dimensions = await getVideoDimensions(videoUrls[0]);

  const canvas = document.createElement('canvas');
  canvas.width = dimensions.width;
  canvas.height = dimensions.height;
  const ctx = canvas.getContext('2d', { alpha: false });
  if (!ctx) throw new Error('Canvas context failed.');

  const stream = canvas.captureStream(STITCH_FPS);
  const { mimeType, sdkMime } = selectBestMime();

  const recorder = new MediaRecorder(stream, {
    mimeType,
    videoBitsPerSecond: STITCH_BITRATE,
  });

  const recordedChunks: Blob[] = [];
  recorder.ondataavailable = (e) => { if (e.data.size > 0) recordedChunks.push(e.data); };
  const recorderStopped = new Promise<void>((res) => { recorder.onstop = () => res(); });

  recorder.start();

  // Draw clips one by one
  for (let i = 0; i < videoUrls.length; i++) {
    await processVideoClip(videoUrls[i], canvas, ctx, (p) => {
      // Composition progress is the first 80% of the total export
      onProgress(0.8 * ((i + p) / videoUrls.length));
    });
  }

  await new Promise(r => setTimeout(r, 200));
  recorder.stop();
  await recorderStopped;
  canvas.remove();

  if (recordedChunks.length === 0) throw new Error('Raw export failed.');

  // Step 2: MediaBunny Remux Pass (The "Right Way" for Flow SDK)
  onProgress(0.85);
  await initEncoders();

  const rawBlob = new Blob(recordedChunks, { type: mimeType });
  const input = new Input({ source: new BlobSource(rawBlob), formats: ALL_FORMATS });
  const output = new Output({
    format: new Mp4OutputFormat({ fastStart: 'in-memory' }), // Fixes the 500 error!
    target: new BufferTarget(),
  });

  const conversion = await Conversion.init({
    input,
    output,
    video: {
      bitrate: STITCH_BITRATE,
      forceTranscode: false, // Fast remux if possible
    }
  });

  if (!conversion.isValid) {
    // If remux failed, the raw recorder blob is our last resort
    console.warn('MediaBunny remux skipped, falling back to raw blob:', conversion.discardedTracks);
    return { blob: rawBlob, sdkMime };
  }

  conversion.onProgress = (p: number) => {
    // MediaBunny pass is the final 20%
    onProgress(0.8 + (p * 0.2));
  };

  await conversion.execute();

  const buffer = output.target.buffer;
  if (!buffer || buffer.byteLength === 0) {
    return { blob: rawBlob, sdkMime };
  }

  onProgress(1);
  return {
    blob: new Blob([buffer], { type: 'video/mp4' }),
    sdkMime: 'video/mp4',
  };
};

import React, { useState, useRef, useEffect } from 'react';
import { TimelineItem, UploadedVideo, GeneratedTransition } from '../types';
import Spinner from './Spinner';

interface TimelineProps {
  timeline: TimelineItem[];
  transitionHints: Record<string, string>;
  transitionRewriters: Record<string, boolean>;
  onHintChange: (slotKey: string, hint: string) => void;
  onRewriterChange: (slotKey: string, enabled: boolean) => void;
  onRemove: (index: number) => void;
  onReorder: (fromIndex: number, toIndex: number) => void;
  onImport: () => void;
  onRetry: () => void;
  isSuggesting: boolean;
}

const EmptySlot: React.FC<{ onClick: () => void }> = ({ onClick }) => (
  <button
    onClick={onClick}
    className="w-72 aspect-video rounded-2xl border border-solid border-white/20 hover:border-white/50 hover:bg-white/5 transition-all flex flex-col items-center justify-center gap-3 group"
  >
    <div className="w-12 h-12 rounded-full border border-white/30 flex items-center justify-center group-hover:scale-110 group-hover:bg-white group-hover:text-black transition-all">
      <span className="material-symbols-outlined text-[24px]">add</span>
    </div>
  </button>
);

const VideoSlot: React.FC<{
  video: UploadedVideo;
  isActive: boolean;
  onRemove: () => void;
  onClick: () => void;
}> = ({ video, isActive, onRemove, onClick }) => {
  const [isHovered, setIsHovered] = useState(false);
  const videoRef = useRef<HTMLVideoElement>(null);

  // Auto-play management for hover
  useEffect(() => {
    if (isHovered && videoRef.current) {
      videoRef.current.currentTime = 0;
      videoRef.current.play().catch(() => {});
    } else if (videoRef.current) {
      videoRef.current.pause();
    }
  }, [isHovered]);

  return (
    <div 
      className={`relative group w-72 aspect-video rounded-2xl overflow-hidden border transition-all duration-500 cursor-pointer bg-black ${
        isActive ? 'border-white ring-4 ring-white/10' : 'border-white/10 hover:border-white/40'
      }`}
      onClick={onClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
    >
      {/* Split Thumbnails: Start (Left) | End (Right) */}
      <div className={`absolute inset-0 flex transition-opacity duration-300 ${isHovered ? 'opacity-0' : 'opacity-100'}`}>
        <div className="flex-1 border-r border-white/15 relative overflow-hidden">
          <img src={video.startThumbnail} className="w-full h-full object-cover" alt="Start Frame" />
          <div className="absolute bottom-2 left-2 px-1.5 py-0.5 bg-black/60 backdrop-blur-md rounded text-[7px] font-black uppercase tracking-wider text-white">
            Start
