        onClick={e => { e.stopPropagation(); onRemove(); }}
        className="absolute top-3 right-3 w-7 h-7 bg-black/60 backdrop-blur-md rounded-full flex items-center justify-center text-lg opacity-0 group-hover:opacity-100 transition-all text-white hover:bg-white hover:text-black z-10"
