const Timeline: React.FC<TimelineProps> = ({
  timeline,
  transitionHints,
  onHintChange,
  onRemove,
  onImport,
  onRetry,
  isSuggesting
}) => {
  const videos = timeline.filter((t): t is { type: 'video'; data: UploadedVideo } => t.type === 'video');
  const transitionItem = timeline.find((t): t is { type: 'transition'; data: GeneratedTransition } => t.type === 'transition');

  const slotA = videos[0]?.data;
  const slotB = videos[1]?.data;

  const key = slotA && slotB ? `${slotA.id}→${slotB.id}` : '';
  const hint = transitionHints[key] || '';

  return (
    <div className="flex items-center justify-center gap-10 w-full max-w-6xl px-10">
      {/* Slot A */}
      <div className="flex flex-col gap-4 items-center">
        <span className="text-[9px] font-black uppercase tracking-[0.05em] text-white">Clip One</span>
        {slotA ? (
          <VideoSlot video={slotA} isActive={false} onRemove={() => onRemove(timeline.findIndex(t => t.data.id === slotA.id))} onClick={() => {}} />
        ) : (
          <EmptySlot onClick={onImport} />
        )}
      </div>

      {/* Transition Slot */}
      <div className="flex flex-col gap-4 items-center">
        <span className="text-[9px] font-black uppercase tracking-[0.05em] text-white">transition description</span>

