          {transitionItem ? (
            <div className="w-full h-full rounded-2xl overflow-hidden border border-white/25 bg-black/40 flex items-center justify-center">
               {transitionItem.data.status === 'generating' ? (
                 <div className="flex flex-col items-center gap-4">
                   <Spinner />
                   <span className="text-[9px] font-bold uppercase tracking-wider text-cyan-400">Rendering...</span>
                 </div>
               ) : transitionItem.data.status === 'done' ? (
                 <video src={transitionItem.data.url} className="w-full h-full object-cover" autoPlay loop muted playsInline />
               ) : (
                 <div className="flex flex-col items-center gap-3 text-white px-6 text-center">
                    <span className="material-symbols-outlined text-[32px] text-red-500">error</span>
                    <span className="text-[9px] font-black uppercase tracking-wider text-red-400">Generation Failed</span>
                    <div className="bg-black/40 border border-white/10 rounded-lg p-2 w-full">
                      <p className="text-[8px] font-medium leading-tight text-white/80 line-clamp-2">
                        {transitionItem.data.error || 'The model was unable to bridge these clips. Try refining your description.'}
                      </p>
                    </div>
                    <button 
                      onClick={(e) => { e.stopPropagation(); onRetry(); }}
                      className="mt-1 w-full py-2 bg-white text-black rounded-full text-[10px] font-bold uppercase tracking-wider transition-all active:scale-95 hover:bg-white/90 shadow-[0_0_20px_rgba(255,255,255,0.1)]"
                    >
                      Retry
                    </button>
                 </div>
               )}
            </div>
          ) : (
            <div className={`w-full h-full rounded-2xl border border-solid transition-all duration-500 p-6 flex flex-col ${
              slotA && slotB ? 'border-white/20 bg-white/5' : 'border-white/5 opacity-40'
            }`}>
              {isSuggesting && !hint ? (
                <div className="flex-1 flex flex-col items-center justify-center gap-2 opacity-50">
                  <div className="w-4 h-4 border-2 border-white/20 border-t-white rounded-full animate-spin" />
                  <span className="text-[9px] font-bold uppercase tracking-wider animate-pulse">Drafting...</span>
                </div>
              ) : (
                <textarea
                  disabled={!slotA || !slotB}
                  value={hint}
                  onChange={e => onHintChange(key, e.target.value)}
                  placeholder="The camera pushes through a window into the next scene..."
                  className="flex-1 bg-transparent text-[11px] font-medium leading-relaxed text-white resize-none focus:outline-none placeholder:text-white/30"
                />
              )}
            </div>
          )}
        </div>
      </div>

      {/* Slot B */}
      <div className="flex flex-col gap-4 items-center">
        <span className="text-[9px] font-black uppercase tracking-[0.05em] text-white">Clip Two</span>
        {slotB ? (
          <VideoSlot video={slotB} isActive={false} onRemove={() => onRemove(timeline.findIndex(t => t.data.id === slotB.id))} onClick={() => {}} />
        ) : (
          <EmptySlot onClick={onImport} />
        )}
      </div>
    </div>
  );
};

