                disabled={isLoading}
                onClick={() => onDurationChange(dur as VeoDuration)}
                className={`px-3 py-1.5 rounded-full text-[9px] font-bold uppercase tracking-wider transition-all duration-300 ${
                  selectedDuration === dur 
                    ? 'bg-cyan-500 text-white shadow-[0_0_15px_rgba(6,182,212,0.2)]' 
                    : 'text-white hover:bg-white/10'
                }`}
              >
                {dur}s
              </button>
            ))}
          </div>
        </div>
      )}
    </div>

    <div className="flex gap-4">
      {canExport && (
        <button
          disabled={isLoading}
          onClick={onExport}
          className="h-12 px-8 border border-white/30 hover:border-white rounded-full text-[10px] font-bold uppercase tracking-wider transition-all duration-200 text-white hover:bg-white/10 disabled:opacity-30"
        >
          Save to Grid
        </button>
      )}
      <button
        disabled={!canGenerate || isLoading}
        onClick={onGenerate}
        className="h-12 px-10 bg-white text-black disabled:opacity-20 rounded-full text-[10px] font-bold uppercase tracking-wider hover:bg-white/90 transition-all duration-200 hover:shadow-[0_0_30px_rgba(255,255,255,0.15)]"
      >
        {isLoading ? 'Processing...' : 'Generate Transitions'}
      </button>
    </div>
  </footer>
);

export default ControlFooter;

